const fs = require('node:fs').promises
const fd = await fs.open('/data/secret.txt', 'r')
const take = async (offset) => {
  const buffer = Buffer.alloc(3)
  const {bytesRead} = await fd.read(buffer, 0, 3, offset)
  console.log(buffer.subarray(0, bytesRead).toString())
}
try {
  await take(0)
  for (const mode of ['pre', 'post']) {
    await fs.readFile('/control/' + mode)
    try { await take(3) } catch (error) { console.log(error.code) }
    await fs.readFile('/control/allow')
    await take(3)
  }
} finally { await fd.close() }

program.js:
const file = std.open('/data/secret.txt', 'r')
const take = () => {
  const bytes = new Uint8Array(3)
  const count = file.read(bytes.buffer, 0, 3)
  if (file.error()) { console.log('refused'); file.clearerr() }
  else console.log(String.fromCharCode(...bytes.slice(0, count)))
}
try {
  take()
  for (const mode of ['pre', 'post']) {
    let control = std.open('/control/' + mode, 'r'); control.readAsString(); control.close()
    file.seek(3, std.SEEK_SET); take()
    control = std.open('/control/allow', 'r'); control.readAsString(); control.close()
    file.seek(3, std.SEEK_SET); take()
  }
} finally { file.close() }

