from pathlib import Path
print(Path('/data/secret.txt').read_text(), end='')
for mode in ['pre', 'post']:
    Path('/control/' + mode).read_text()
    try:
        print(Path('/data/secret.txt').read_text(), end='')
    except OSError as error:
        print(type(error).__name__)
    Path('/control/allow').read_text()
    print(Path('/data/secret.txt').read_text(), end='')

